import{_ as a,a0 as n,w as l,s as u,I as r,x as e,a1 as o,A as i,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Brave 浏览器中使用画中画模式 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Brave 浏览器中使用画中画模式 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Brave 浏览器中使用画中画模式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Brave 浏览器中使用画中画模式 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20220929 How to Use Picture in Picture Mode in Brave Browser","title":"如何在 Brave 浏览器中使用画中画模式","tag":"202210","desc":""},"relativePath":"202210/20220929 How to Use Picture in Picture Mode in Brave Browser.md","filePath":"[post].md"}'),d={name:"202210/20220929 How to Use Picture in Picture Mode in Brave Browser.md"};function m(f,t,v,b,g,B){const p=n("Link");return l(),u("div",null,[t[21]||(t[21]=r("h1",{id:"如何在-brave-浏览器中使用画中画模式",tabindex:"-1"},[e("如何在 Brave 浏览器中使用画中画模式 "),r("a",{class:"header-anchor",href:"#如何在-brave-浏览器中使用画中画模式","aria-label":"Permalink to “如何在 Brave 浏览器中使用画中画模式”"},"​")],-1)),t[22]||(t[22]=r("p",null,[r("img",{src:"https://img.linux.net.cn/data/attachment/album/202210/13/003034agqsflug771cl3uj.jpg",alt:""})],-1)),r("blockquote",null,[r("p",null,[t[1]||(t[1]=e("Brave 是一款出色的类似于 Chrome，但可 ",-1)),o(p,{href:"https://itsfoss.com/open-source-browsers-linux/"},{default:i(()=>[...t[0]||(t[0]=[e("替代 Chrome 的网络浏览器",-1)])]),_:1}),t[2]||(t[2]=e("。",-1))])]),r("p",null,[o(p,{href:"https://itsfoss.com/brave-vs-firefox/"},{default:i(()=>[...t[3]||(t[3]=[e("Firefox 和 Brave",-1)])]),_:1}),t[4]||(t[4]=e(" 是我喜欢在 Linux 系统上使用的两种浏览器。两者都有不同的优势。",-1))]),t[23]||(t[23]=s('<p>Firefox 比 Brave 做得更好的一件事就是画中画（PIP）模式，它适用于 YouTube、Netflix 和大多数流媒体网站。</p><p>Brave 也有画中画模式，但它是如此隐藏，以至于你觉得它根本没有 PIP 支持。</p><p>内置画中画适用于某些网站（如 YouTube），但可能不适用于其他网站（如 Prime Video）。不用担心！你可以为此使用专用扩展。</p><p>让我在本教程中展示这两种方法。</p><h3 id="方法-1-在视频上双击右键" tabindex="-1">方法 1：在视频上双击右键 <a class="header-anchor" href="#方法-1-在视频上双击右键" aria-label="Permalink to “方法 1：在视频上双击右键”">​</a></h3><p><strong>技巧是依次单击两次右键，你应该会看到画中画模式选项。</strong></p><p>让我通过一个例子来说明这一点。在 Brave 中播放 YouTube 视频。现在右键单击视频。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/getting-picture-in-picture-in-brave-1.webp" alt="第一次右键单击后将光标从上下文菜单稍微移开"></p><p>再次右键单击。它应该在视频上，但不在上一个上下文菜单上，而在视频的其他地方。</p><p>现在你应该看到另一个带有画中画选项的上下文菜单。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/getting-picture-in-picture-in-brave-2.webp" alt="你应该在第二次右键单击中看到画中画选项"></p><p>选择画中画，视频将从窗口中弹出。你可以将其移动到浏览器中的任何位置。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/brave-picture-in-picture-youtube.webp" alt="Brave 浏览器画中画模式"></p><p>当你使用其他应用时，你还可以让它在屏幕上的任何位置播放。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/brave-playing-picture-in-picture-mode-on-screen.webp" alt="Brave 在画中画模式中播放影片"></p><p>在最近的 Brave 版本中，你可以根据自己的喜好调整弹出窗口的大小。</p><p>我不明白为什么 Brave 把它隐藏成这样。为什么不突出它？</p><p>无论如何，这适用于 YouTube 等网站，但可能不适用于 Prime 视频。如果你愿意，你可以安装一个扩展。</p><h3 id="方法-2-使用画中画扩展" tabindex="-1">方法 2：使用画中画扩展 <a class="header-anchor" href="#方法-2-使用画中画扩展" aria-label="Permalink to “方法 2：使用画中画扩展”">​</a></h3><p>谷歌提供了一个官方插件，可让你在谷歌 Chrome 中获得画中画功能。由于 Brave 基于 Chromium，你可以在 Brave 中使用相同的扩展。</p>',20)),r("blockquote",null,[r("p",null,[r("strong",null,[o(p,{href:"https://chrome.google.com/webstore/detail/picture-in-picture-extens/hkgfoiooedgoejojocmhlaklaeopbecg/related?hl=en-US"},{default:i(()=>[...t[5]||(t[5]=[e("画中画扩展",-1)])]),_:1})])])]),t[24]||(t[24]=s('<p>进入扩展页面并点击 “<ruby>添加到 Brave<rt>Add to Brave</rt></ruby>” 按钮。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/picture-in-picture-extension-google-chrome-web.png" alt="为 Brave 添加画中画扩展"></p><p>当你单击它时，它会提示添加扩展的选项。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/add-picture-in-picture-extension-to-brave.webp" alt="添加扩展"></p><p>添加扩展后，你应该会在浏览器的右上角看到它。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/picture-in-picture-extension.png" alt="使用画中画扩展"></p><p>播放视频时，单击该扩展图标，视频应该会弹出。</p><h3 id="你能在-brave-中启用-pip-模式吗" tabindex="-1">你能在 Brave 中启用 PIP 模式吗？ <a class="header-anchor" href="#你能在-brave-中启用-pip-模式吗" aria-label="Permalink to “你能在 Brave 中启用 PIP 模式吗？”">​</a></h3><p>画中画模式已成为休闲流媒体消费的必备功能。我觉得奇怪的是，Brave 和其他浏览器没有足够重视它。 Firefox 处理得很好。</p><p>我希望这个快速的小技巧可以帮助你在 Brave 浏览器中获得 PIP 体验。你更喜欢这两种方法中的哪一种？右键单击还是扩展？</p><hr>',11)),r("p",null,[t[7]||(t[7]=e("via: ",-1)),o(p,{href:"https://itsfoss.com/picture-in-picture-brave/"},{default:i(()=>[...t[6]||(t[6]=[e("https://itsfoss.com/picture-in-picture-brave/",-1)])]),_:1})]),r("p",null,[t[12]||(t[12]=e("作者：",-1)),o(p,{href:"https://itsfoss.com/"},{default:i(()=>[...t[8]||(t[8]=[e("Abhishek Prakash",-1)])]),_:1}),t[13]||(t[13]=e(" 选题：",-1)),o(p,{href:"https://github.com/lkxed"},{default:i(()=>[...t[9]||(t[9]=[e("lkxed",-1)])]),_:1}),t[14]||(t[14]=e(" 译者：",-1)),o(p,{href:"https://github.com/geekpi"},{default:i(()=>[...t[10]||(t[10]=[e("geekpi",-1)])]),_:1}),t[15]||(t[15]=e(" 校对：",-1)),o(p,{href:"https://github.com/wxy"},{default:i(()=>[...t[11]||(t[11]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[18]||(t[18]=e("本文由 ",-1)),o(p,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[16]||(t[16]=[e("LCTT",-1)])]),_:1}),t[19]||(t[19]=e(" 原创编译，",-1)),o(p,{href:"https://linux.cn/"},{default:i(()=>[...t[17]||(t[17]=[e("Linux中国",-1)])]),_:1}),t[20]||(t[20]=e(" 荣誉推出",-1))])])}const w=a(d,[["render",m]]);export{x as __pageData,w as default};
